// Rotates `a` left by `offset` and returns the rotated vector.
// For each i in [0, n): b[i] = a[(i + offset) % n].
pub fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n;
    let mut b = Vec::with_capacity(n);

    for i in 0..n {
        let idx = (i + k) % n;
        b.push(a[idx]);
    }

    b
}

